const HTML = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<title>Control de Retiros</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F2F3F6; --panel:#FFFFFF; --panel-2:#F7F8FA; --ink:#1F2430; --muted:#6B7280; --label:#2B303B;\n  --line:#E3E6EB; --field:#D9DDE3; --red:#C8102E; --red-dk:#A00C24; --red-soft:#FCEBEE; --red-light:#E9A3AE;\n  --steel:#3B414A; --steel-soft:#E8EBEF; --ok:#17784A; --ok-dk:#0F5C37; --ok-soft:#E5F5EC; --ok-line:#A6DABD;\n  --font:\"Inter\",-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;\n  --shadow:0 6px 24px rgba(30,36,48,.07);\n  color-scheme:light; box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);\n}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\n*,*::before,*::after{box-sizing:inherit}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:13px;line-height:1.45;-webkit-text-size-adjust:100%}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--panel)}\nbutton,input,select{font:inherit;color:inherit}\n:focus-visible{outline:2px solid #F29AA8;outline-offset:2px}\n.hidden{display:none!important}\n.rol-transportista .admin-only{display:none!important}\n\n/* Header */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:6;background:var(--panel);border-bottom:1px solid var(--line);box-shadow:0 1px 0 rgba(0,0,0,.02)}\n.top-in{max-width:1280px;margin:0 auto;padding:8px 18px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;min-height:52px}\n.brand{display:flex;align-items:center;gap:9px}\n.brand h1{font-size:15px;font-weight:700;margin:0;letter-spacing:-.1px}\n.tabs{display:flex;gap:4px;background:var(--panel-2);border:1px solid var(--line);border-radius:9px;padding:3px}\n.tabs button{appearance:none;border:0;background:transparent;border-radius:7px;padding:5px 12px;font-size:12.5px;font-weight:600;color:var(--muted);cursor:pointer}\n.tabs button.on{background:var(--red);color:#fff}\n.who{margin-left:auto;display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted)}\n.sync{display:flex;align-items:center;gap:5px}\n.sync i{width:7px;height:7px;border-radius:50%;background:#B8BCC2;display:inline-block}\n.sync.on i{background:var(--ok)}\n.user{display:flex;align-items:center;gap:6px;background:var(--panel-2);border:1px solid var(--line);border-radius:20px;padding:3px 10px 3px 4px;color:var(--ink);font-weight:600}\n.user .av{width:20px;height:20px;border-radius:50%;background:var(--red);color:#fff;font-size:10.5px;display:grid;place-items:center}\n.user small{font-weight:500;color:var(--muted)}\n.link{appearance:none;border:0;background:none;color:var(--red);font-weight:600;cursor:pointer;padding:4px 2px;font-size:12px}\n\nmain{max-width:1280px;margin:0 auto;padding:16px 18px 24px}\n.card{background:var(--panel);border-radius:14px;box-shadow:var(--shadow);border:1px solid rgba(227,230,235,.6)}\n\n/* Filters card */\n.fcard{padding:14px 16px 16px;margin-bottom:14px}\n.fhead{display:flex;align-items:center;gap:6px;color:var(--steel);font-size:12.5px;font-weight:500;margin-bottom:10px}\n.fgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:10px 14px;align-items:end}\n.fl{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:600;color:var(--label);min-width:0}\n.fend{grid-column:span 2;display:flex;align-items:center;justify-content:space-between;gap:12px;height:32px}\n.inl{display:flex;align-items:center;gap:6px;font-size:11.5px;font-weight:600;color:var(--label);white-space:nowrap;cursor:pointer}\n.inl input{width:15px;height:15px;accent-color:var(--red);margin:0}\ninput[type=text],input[type=password],input[type=date],input[type=search],select{border:1px solid var(--field);background:var(--panel);border-radius:8px;padding:0 10px;height:32px;width:100%;font-size:12.5px;min-width:0}\ninput::placeholder{color:#9AA1AC}\ninput:focus,select:focus{border-color:var(--red);outline:none;box-shadow:0 0 0 3px var(--red-soft)}\ninput:disabled{background:var(--panel-2);color:#A0A6B0}\n.factions{display:flex;gap:8px;justify-content:flex-end}\n.ibtn{appearance:none;border:0;border-radius:7px;width:46px;height:32px;display:grid;place-items:center;cursor:pointer;background:var(--red);color:#fff;transition:background .15s,transform .08s}\n.ibtn:hover{background:var(--red-dk)}\n.ibtn.soft{background:var(--red-light)}\n.ibtn.soft:hover{background:#DE8998}\n.ibtn:active{transform:scale(.96)}\n\n/* Buttons */\n.btn{appearance:none;border:1px solid var(--red);background:var(--red);color:#fff;font-weight:600;border-radius:8px;padding:0 13px;height:32px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap;font-size:12.5px;transition:background .15s}\n.btn:hover{background:var(--red-dk);border-color:var(--red-dk)}\n.btn.ghost{background:transparent;color:var(--red)}\n.btn.ghost:hover{background:var(--red-soft)}\n.btn.plain{border-color:var(--field);background:var(--panel);color:var(--steel)}\n.btn.plain:hover{background:var(--panel-2)}\n.btn.green{background:var(--ok);border-color:var(--ok)}\n.btn.green:hover{background:var(--ok-dk);border-color:var(--ok-dk)}\n.btn.sm{height:28px;padding:0 10px;font-size:12px}\n.btn[disabled]{opacity:.5;cursor:not-allowed}\n.icon-btn{appearance:none;border:0;background:transparent;color:var(--muted);border-radius:6px;cursor:pointer;width:28px;height:28px;font-size:13px}\n.icon-btn:hover{background:var(--panel-2);color:var(--ink)}\n.icon-btn.del:hover{color:var(--red);background:var(--red-soft)}\n\n/* List card */\n.lhead{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}\n.lhead h2{margin:0;font-size:13.5px;font-weight:700;margin-right:auto}\n.lhead h2 span{color:var(--muted);font-weight:500}\n.legend{display:flex;gap:12px;font-size:11.5px;color:var(--muted)}\n.legend span{display:flex;align-items:center;gap:5px}\n.sw{width:11px;height:11px;border-radius:3px;display:inline-block;border:1px solid var(--line)}\n.sw.d{background:var(--ok-soft);border-color:var(--ok-line);box-shadow:inset 3px 0 0 var(--ok)}\n\n.selbar{position:sticky;bottom:calc(10px + env(safe-area-inset-bottom,0px));z-index:4;display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:var(--ink);color:#fff;border-radius:10px;padding:8px 12px;margin:0 0 12px;box-shadow:0 6px 20px rgba(20,22,26,.25);font-size:12.5px}\n.selbar>span{margin-right:auto;font-weight:600}\n.selbar .btn.plain{background:transparent;color:#fff;border-color:#5B616A}\n\n.tbl-wrap{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:12.5px}\nth,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:middle}\nth{font-size:11px;color:var(--muted);font-weight:600;background:var(--panel-2);white-space:nowrap}\nth:first-child,td:first-child{padding-left:16px}\nth[data-sort]{cursor:pointer;user-select:none}\nth[data-sort]:hover{color:var(--ink)}\nth .ar{font-size:9px;margin-left:3px;color:var(--red)}\ntr:last-child td{border-bottom:0}\ntbody tr{transition:background .25s}\ntbody tr:hover td{background:#FAFBFC}\ntbody tr.d td{background:var(--ok-soft)}\ntbody tr.d td:first-child{box-shadow:inset 3px 0 0 var(--ok)}\ntbody tr.d:hover td{background:#D9F0E3}\ntbody tr.click{cursor:pointer}\ntd.n,th.n{text-align:right;font-variant-numeric:tabular-nums}\ntr.total td{font-weight:700;background:var(--panel-2)}\n.ref{font-weight:600}\n.chk{width:15px;height:15px;accent-color:var(--red);cursor:pointer;margin:0;vertical-align:middle}\n.tag{display:inline-block;font-weight:600;font-size:11px;padding:2px 7px;border-radius:5px;white-space:nowrap}\n.tag.cam{background:var(--red-soft);color:var(--red-dk)}\n.tag.cont{background:var(--steel-soft);color:var(--steel)}\n.tag.none{color:var(--muted);font-weight:500;padding-left:0}\n.st{appearance:none;border:1px solid var(--field);background:var(--panel);color:var(--steel);border-radius:20px;padding:0 10px 0 7px;height:25px;font-size:11.5px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:5px;white-space:nowrap;transition:all .15s}\n.st::before{content:\"\";width:12px;height:12px;border-radius:50%;border:2px solid #B8BCC2;box-sizing:border-box}\n.st:hover{border-color:var(--ok);color:var(--ok)}\n.st.d{background:var(--ok);border-color:var(--ok);color:#fff}\n.st.d::before{content:\"✓\";border:0;background:#fff;color:var(--ok);font-size:8.5px;line-height:12px;text-align:center;font-weight:700}\n.st small{font-weight:500;opacity:.85;font-size:10.5px}\n.empty{padding:34px 16px;text-align:center;color:var(--muted)}\n.empty strong{display:block;color:var(--ink);font-size:14px;margin-bottom:3px}\n\n.cards{display:none}\n.rcard{padding:11px 14px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:auto 1fr auto;gap:5px 10px;align-items:start;transition:background .25s}\n.rcard:last-child{border-bottom:0}\n.rcard.d{background:var(--ok-soft);box-shadow:inset 3px 0 0 var(--ok)}\n.rcard .meta{grid-column:2/4;display:grid;grid-template-columns:1fr 1fr;gap:2px 10px;font-size:11.5px;color:var(--muted)}\n.rcard .meta b{color:var(--ink);font-weight:500}\n.rcard .stw{grid-column:2/4}\n.rcard .stw .st{width:100%;justify-content:center;height:32px;font-size:12.5px}\n.rcard .acts{display:flex}\n.rcard .chk{margin-top:2px}\n\n/* Stats */\n.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px}\n.kpi{padding:12px 14px}\n.kpi b{display:block;font-size:22px;font-weight:700;line-height:1.15;letter-spacing:-.3px}\n.kpi span{color:var(--muted);font-size:11.5px}\n.kpi.red b{color:var(--red)} .kpi.okk b{color:var(--ok)}\n.prog{height:5px;border-radius:3px;background:var(--steel-soft);overflow:hidden}\n.prog i{display:block;height:100%;background:var(--ok);transition:width .35s ease}\n.kpi .prog{margin-top:7px}\n.sect{margin-bottom:14px;overflow:hidden}\n.sect-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 16px}\n.sect-h h2{font-size:13.5px;font-weight:700;margin:0;margin-right:auto}\n.sect-h small{color:var(--muted);font-size:11.5px}\n.note{font-size:11.5px;color:var(--muted);padding:8px 16px 12px;margin:0}\n.qr{display:flex;gap:6px;flex-wrap:wrap}\n.qr button{appearance:none;border:1px solid var(--field);background:var(--panel);border-radius:20px;padding:0 11px;height:28px;font-weight:600;font-size:11.5px;cursor:pointer;color:var(--steel)}\n.qr button.on{background:var(--red);border-color:var(--red);color:#fff}\n.chart{overflow-x:auto;padding:0 16px 4px}\n.bars{display:flex;align-items:flex-end;gap:10px;height:170px;min-width:min-content;padding-top:20px;border-bottom:1px solid var(--line)}\n.bcol{appearance:none;border:0;background:transparent;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;width:42px;flex:none;cursor:pointer}\n.bcol .v{font-size:11.5px;font-weight:700;margin-bottom:3px}\n.bstack{width:26px;display:flex;flex-direction:column-reverse;border-radius:4px 4px 0 0;overflow:hidden}\n.bstack i{display:block;width:100%}\n.bstack .c1{background:var(--red)} .bstack .c2{background:var(--steel)}\n.bcol:hover .bstack{filter:brightness(1.12)}\n.bcol:hover .v{color:var(--red)}\n.blab{display:flex;gap:10px;min-width:min-content}\n.blab span{width:42px;flex:none;text-align:center;font-size:10.5px;color:var(--muted);padding-top:4px}\n.ckey{display:flex;gap:14px;font-size:11.5px;color:var(--muted);padding:6px 16px 12px}\n.ckey span{display:flex;align-items:center;gap:5px}\n.ckey i{width:10px;height:10px;border-radius:2px;display:inline-block}\n.tip{position:fixed;z-index:25;background:var(--ink);color:#fff;font-size:11.5px;padding:6px 9px;border-radius:6px;pointer-events:none;max-width:220px}\n.minibar{display:inline-block;vertical-align:middle;height:6px;border-radius:3px;background:var(--red);margin-right:7px}\n.pct{display:inline-flex;align-items:center;gap:6px;justify-content:flex-end}\n.pct .prog{width:54px;display:inline-block}\n\n/* Modal */\n.ov{position:fixed;inset:0;background:rgba(25,28,33,.45);z-index:20;display:flex;align-items:center;justify-content:center;padding:16px}\n.modal{background:var(--panel);border-radius:14px;width:100%;max-width:600px;max-height:calc(100% - 20px);overflow:auto;box-shadow:0 18px 50px rgba(0,0,0,.25)}\n.modal header{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--panel);z-index:1}\n.modal header h2{margin:0;font-size:14.5px;font-weight:700}\n.modal .body{padding:14px 16px;display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.modal .body .full{grid-column:1/-1}\n.modal footer{display:flex;gap:8px;justify-content:flex-end;padding:10px 16px 14px;border-top:1px solid var(--line);position:sticky;bottom:0;background:var(--panel);flex-wrap:wrap}\n.fieldset{grid-column:1/-1;border:1px solid var(--line);border-radius:10px;padding:10px 12px 12px;display:grid;grid-template-columns:1fr 1fr;gap:12px;background:var(--panel-2);margin:0}\n.fieldset.okf{background:var(--ok-soft);border-color:var(--ok-line)}\n.fieldset legend{font-weight:700;font-size:12px;padding:0 5px}\n.switch{display:flex;align-items:center;gap:8px;font-weight:600;cursor:pointer;align-self:end;height:32px;font-size:12.5px}\n.switch input{width:16px;height:16px;accent-color:var(--ok)}\n.hint{grid-column:1/-1;font-size:11.5px;color:var(--muted);margin:0}\n.err{grid-column:1/-1;color:var(--red-dk);background:var(--red-soft);border-radius:8px;padding:7px 10px;font-size:12px;margin:0}\n.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:#fff;padding:9px 14px;border-radius:8px;z-index:30;font-size:12.5px;max-width:90%;display:flex;gap:12px;align-items:center}\n.toast button{appearance:none;border:0;background:transparent;color:#FF8A9C;font-weight:700;cursor:pointer;padding:2px 4px}\n\n/* Login */\n.login{min-height:100vh;display:grid;place-items:center;padding:20px}\n.lcard{width:100%;max-width:360px;padding:26px 24px 22px}\n.lcard .brand{justify-content:center;margin-bottom:4px}\n.lcard .brand h1{font-size:17px}\n.lcard p.sub{text-align:center;color:var(--muted);margin:0 0 18px;font-size:12.5px}\n.lcard form{display:grid;gap:12px}\n.lcard .btn{height:36px;font-size:13px}\n.lcard .foot{font-size:11.5px;color:var(--muted);text-align:center;margin:14px 0 0}\n\n@media (max-width:760px){\n  .tbl-wrap.records{display:none}\n  .cards{display:block}\n  .top-in{padding:8px 12px;gap:8px}\n  .who{margin-left:0;width:100%;justify-content:space-between}\n  .tabs{margin-left:auto}\n  main{padding:12px}\n  .fgrid{grid-template-columns:1fr 1fr}\n  .fend{grid-column:1/-1}\n  .factions{grid-column:1/-1}\n  .kpis{grid-template-columns:repeat(2,1fr)}\n  .kpi.wide{grid-column:1/-1}\n  input[type=text],input[type=password],input[type=date],input[type=search],select{font-size:13.5px;height:34px}\n  .ov{align-items:flex-end;padding:0}\n  .modal{border-radius:14px 14px 0 0;max-height:92%;padding-bottom:env(safe-area-inset-bottom,0px)}\n  .modal .body,.fieldset{grid-template-columns:1fr}\n}\n@media (prefers-reduced-motion:no-preference){\n  .flash td,.rcard.flash{animation:flash .9s ease-out}\n  @keyframes flash{0%{background:#BDE7CF}100%{}}\n  .modal{animation:pop .16s ease-out}\n  @keyframes pop{from{transform:translateY(8px);opacity:.6}}\n}\n</style>\n</head>\n<body>\n\n<!-- Login -->\n<section id=\"login\" class=\"login hidden\">\n  <div class=\"card lcard\">\n    <div class=\"brand\">\n      <svg width=\"28\" height=\"28\" viewBox=\"0 0 34 34\" aria-hidden=\"true\"><rect width=\"34\" height=\"34\" rx=\"8\" fill=\"#C8102E\"/><path d=\"M6 21V11h13v10M19 14h5l4 4v3h-9\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/><circle cx=\"11\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/><circle cx=\"24\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/></svg>\n      <h1>Control de Retiros</h1>\n    </div>\n    <p class=\"sub\">Ingresa tu nombre y la clave asignada</p>\n    <form id=\"l-form\" autocomplete=\"on\">\n      <label class=\"fl\">Nombre<input type=\"text\" id=\"l-nom\" placeholder=\"Tu nombre\" autocomplete=\"name\" required></label>\n      <label class=\"fl\">Clave<input type=\"password\" id=\"l-clave\" placeholder=\"Clave\" autocomplete=\"current-password\" required></label>\n      <p class=\"err hidden\" id=\"l-err\"></p>\n      <button class=\"btn\" type=\"submit\" id=\"l-btn\">Entrar</button>\n    </form>\n    <p class=\"foot\">La clave la entrega el administrador.</p>\n  </div>\n</section>\n\n<!-- App -->\n<div id=\"app\" class=\"hidden\">\n<header class=\"top\">\n  <div class=\"top-in\">\n    <div class=\"brand\">\n      <svg width=\"26\" height=\"26\" viewBox=\"0 0 34 34\" aria-hidden=\"true\"><rect width=\"34\" height=\"34\" rx=\"8\" fill=\"#C8102E\"/><path d=\"M6 21V11h13v10M19 14h5l4 4v3h-9\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/><circle cx=\"11\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/><circle cx=\"24\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/></svg>\n      <h1>Control de Retiros</h1>\n    </div>\n    <nav class=\"tabs\">\n      <button type=\"button\" id=\"nav-reg\" class=\"on\">Registros</button>\n      <button type=\"button\" id=\"nav-est\">Estadísticas</button>\n    </nav>\n    <div class=\"who\">\n      <span class=\"sync\" id=\"sync\"><i></i><span>Conectando…</span></span>\n      <span class=\"user\"><span class=\"av\" id=\"u-av\">?</span><span id=\"u-nom\"></span><small id=\"u-rol\"></small></span>\n      <button class=\"link\" type=\"button\" id=\"btn-out\">Salir</button>\n    </div>\n  </div>\n</header>\n\n<main>\n  <section id=\"v-reg\">\n    <div class=\"card fcard\">\n      <div class=\"fhead\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0\"/><circle cx=\"16\" cy=\"6\" r=\"2\"/><circle cx=\"10\" cy=\"12\" r=\"2\"/><circle cx=\"18\" cy=\"18\" r=\"2\"/></svg>Filtros</div>\n      <div class=\"fgrid\">\n        <label class=\"fl\">Embarque<input type=\"search\" id=\"f-emb\" placeholder=\"Embarque\"></label>\n        <label class=\"fl\">Referencia<input type=\"search\" id=\"f-ref\" placeholder=\"Referencia\"></label>\n        <label class=\"fl\">Almacenadora<input type=\"search\" id=\"f-alm\" placeholder=\"Almacenadora\" list=\"dl-alm\"></label>\n        <label class=\"fl\">Bodega<input type=\"search\" id=\"f-bod\" placeholder=\"Bodega\" list=\"dl-bod\"></label>\n        <label class=\"fl\">Retiro desde<input type=\"date\" id=\"f-desde\"></label>\n        <label class=\"fl\">Hasta<input type=\"date\" id=\"f-hasta\"></label>\n        <label class=\"fl\">Estado<select id=\"f-est\"><option value=\"all\">Todos</option><option value=\"p\">Pendientes de descarga</option><option value=\"d\">Descargados en CD</option></select></label>\n        <div class=\"fend\">\n          <label class=\"inl\"><input type=\"checkbox\" id=\"f-todas\"> Todas las fechas</label>\n          <div class=\"factions\">\n          <button class=\"ibtn\" type=\"button\" id=\"f-go\" title=\"Buscar\" aria-label=\"Buscar\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M20 20l-3.5-3.5\"/></svg></button>\n          <button class=\"ibtn soft\" type=\"button\" id=\"f-reset\" title=\"Restablecer filtros\" aria-label=\"Restablecer filtros\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 12a8 8 0 1 1-2.34-5.66\"/><path d=\"M20 4v5h-5\"/></svg></button>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div id=\"selbar\" class=\"selbar hidden\">\n      <span id=\"selcount\"></span>\n      <button class=\"btn sm green\" id=\"btn-markd\" type=\"button\">✓ Marcar descargadas</button>\n      <button class=\"btn sm admin-only\" id=\"btn-assign\" type=\"button\">Asignar transporte</button>\n      <button class=\"btn sm plain\" id=\"btn-markp\" type=\"button\">Marcar pendientes</button>\n      <button class=\"btn sm plain\" id=\"btn-unsel\" type=\"button\">Quitar selección</button>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"lhead\">\n        <h2>Registros <span id=\"count\"></span></h2>\n        <div class=\"legend\"><span><i class=\"sw d\"></i>Descargado en CD</span><span><i class=\"sw\"></i>Pendiente</span></div>\n        <button class=\"btn admin-only\" id=\"btn-new\" type=\"button\">+ Nuevo registro</button>\n      </div>\n      <div class=\"tbl-wrap records\"><table id=\"tbl\"></table></div>\n      <div class=\"cards\" id=\"cards\"></div>\n    </div>\n  </section>\n\n  <section id=\"v-est\" class=\"hidden\">\n    <div class=\"card fcard\">\n      <div class=\"fhead\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0\"/><circle cx=\"16\" cy=\"6\" r=\"2\"/><circle cx=\"10\" cy=\"12\" r=\"2\"/><circle cx=\"18\" cy=\"18\" r=\"2\"/></svg>Filtros</div>\n      <div class=\"fgrid\">\n        <label class=\"fl\">Retiro desde<input type=\"date\" id=\"s-from\"></label>\n        <label class=\"fl\">Hasta<input type=\"date\" id=\"s-to\"></label>\n        <div class=\"fl\" style=\"grid-column:span 2\">Periodo rápido\n          <div class=\"qr\" id=\"qr\">\n            <button type=\"button\" data-range=\"7\">7 días</button>\n            <button type=\"button\" data-range=\"30\">30 días</button>\n            <button type=\"button\" data-range=\"mes\">Este mes</button>\n            <button type=\"button\" data-range=\"all\">Todo</button>\n          </div>\n        </div>\n        <div class=\"factions\"><button class=\"btn ghost\" id=\"s-csv\" type=\"button\">Exportar CSV</button></div>\n      </div>\n    </div>\n    <div class=\"kpis\" id=\"kpis\"></div>\n    <div class=\"card sect\">\n      <div class=\"sect-h\"><h2>Unidades por fecha de retiro</h2><small>Toca una barra para ver ese día</small></div>\n      <div class=\"chart\" id=\"chart\"></div>\n      <div class=\"ckey\"><span><i style=\"background:var(--red)\"></i>Camiones 8 ton</span><span><i style=\"background:var(--steel)\"></i>Contenedores</span></div>\n    </div>\n    <div class=\"card sect\"><div class=\"sect-h\"><h2>Por fecha de retiro</h2><small>Toca una fila para ver el detalle</small></div><div class=\"tbl-wrap\"><table id=\"t-fecha\"></table></div></div>\n    <div class=\"card sect\"><div class=\"sect-h\"><h2>Por almacenadora</h2></div><div class=\"tbl-wrap\"><table id=\"t-alm\"></table></div>\n      <p class=\"note\">Una unidad que llevó referencias de varias almacenadoras cuenta una vez en cada una; por eso la suma puede superar el total general.</p></div>\n    <div class=\"card sect\"><div class=\"sect-h\"><h2>Por bodega</h2></div><div class=\"tbl-wrap\"><table id=\"t-bod\"></table></div>\n      <p class=\"note\">Misma regla: una unidad compartida entre bodegas se cuenta en cada bodega que atendió.</p></div>\n  </section>\n</main>\n</div>\n\n<div id=\"modal-root\"></div>\n<datalist id=\"dl-alm\"></datalist>\n<datalist id=\"dl-bod\"></datalist>\n\n<script>\n(function(){\n  \"use strict\";\n  var regs = [], sel = new Set(), flash = new Set();\n  var view = \"reg\", sortKey = \"fechaRetiro\", sortDir = -1, qRange = \"all\";\n  var ses = null, busy = 0, pollTimer = null;\n  var API = \"/api/registros\", SES_KEY = \"cr_sesion\";\n  var F = { emb:\"\", ref:\"\", alm:\"\", bod:\"\", desde:\"\", hasta:\"\", todas:false, estado:\"all\" };\n  var ROL = { admin:\"Administrador\", transportista:\"Transportista\" };\n\n  var $ = function(id){ return document.getElementById(id); };\n  function esc(s){ return String(s == null ? \"\" : s).replace(/[&<>\"']/g, function(c){ return {\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]; }); }\n  function fmt(d){ if(!d) return \"—\"; var p = d.split(\"-\"); return p.length===3 ? p[2]+\"/\"+p[1]+\"/\"+p[0] : d; }\n  function fmtShort(d){ var p = (d||\"\").split(\"-\"); return p.length===3 ? p[2]+\"/\"+p[1] : d; }\n  function today(off){ var d=new Date(); d.setDate(d.getDate()+(off||0)); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); }\n  function hora(){ var d=new Date(); return String(d.getHours()).padStart(2,\"0\")+\":\"+String(d.getMinutes()).padStart(2,\"0\"); }\n  function newId(){ return \"r\" + Date.now().toString(36) + Math.random().toString(36).slice(2,8); }\n  function isAdmin(){ return !!ses && ses.rol === \"admin\"; }\n  function unitKey(r){ return (r.fechaRetiro && r.tipo && r.unidad) ? r.fechaRetiro+\"|\"+r.tipo+\"|\"+r.unidad : null; }\n  function unitLabel(tipo, n){ return (tipo===\"camion\" ? \"Camión 8 ton\" : \"Contenedor\") + \" #\" + n; }\n  function bodyOf(r){ var b = Object.assign({}, r); delete b.id; delete b.modificadoPor; return b; }\n  function tagHtml(r){\n    if(!r.tipo || !r.unidad) return '<span class=\"tag none\">Sin asignar</span>';\n    return '<span class=\"tag '+(r.tipo===\"camion\"?\"cam\":\"cont\")+'\">'+esc(unitLabel(r.tipo, r.unidad))+'</span>';\n  }\n  function stHtml(r){\n    return r.descargado\n      ? '<button class=\"st d\" type=\"button\" data-desc=\"'+esc(r.id)+'\" title=\"Toca para marcar como pendiente\">Descargado'+(r.fechaDescarga?' <small>'+esc(fmtShort(r.fechaDescarga))+'</small>':'')+'</button>'\n      : '<button class=\"st\" type=\"button\" data-desc=\"'+esc(r.id)+'\" title=\"Toca para confirmar la descarga en CD\">Confirmar descarga</button>';\n  }\n  var toastTimer;\n  function toast(msg, undo){\n    var old = document.querySelector(\".toast\"); if(old) old.remove();\n    var t = document.createElement(\"div\"); t.className=\"toast\";\n    var s = document.createElement(\"span\"); s.textContent = msg; t.appendChild(s);\n    if(undo){ var b=document.createElement(\"button\"); b.type=\"button\"; b.textContent=\"Deshacer\"; b.onclick=function(){ t.remove(); undo(); }; t.appendChild(b); }\n    document.body.appendChild(t); clearTimeout(toastTimer); toastTimer = setTimeout(function(){ t.remove(); }, undo?5000:2800);\n  }\n  function setSync(text, on){ var s=$(\"sync\"); s.querySelector(\"span\").textContent=text; s.classList.toggle(\"on\", !!on); }\n\n  /* ---------- Sesión ---------- */\n  function loadSes(){ try{ var s = JSON.parse(localStorage.getItem(SES_KEY) || \"null\"); if(s && s.nombre && s.clave) ses = s; }catch(e){} }\n  function saveSes(){ try{ localStorage.setItem(SES_KEY, JSON.stringify(ses)); }catch(e){} }\n  function showLogin(msg){\n    $(\"app\").classList.add(\"hidden\"); $(\"login\").classList.remove(\"hidden\");\n    var e = $(\"l-err\"); if(msg){ e.textContent = msg; e.classList.remove(\"hidden\"); } else e.classList.add(\"hidden\");\n    if(ses && ses.nombre) $(\"l-nom\").value = ses.nombre;\n    setTimeout(function(){ ($(\"l-nom\").value ? $(\"l-clave\") : $(\"l-nom\")).focus(); }, 30);\n  }\n  function logout(msg){\n    var nombre = ses && ses.nombre;\n    ses = null; try{ localStorage.removeItem(SES_KEY); }catch(e){}\n    if(pollTimer){ clearInterval(pollTimer); pollTimer = null; }\n    regs = []; sel.clear(); closeModal();\n    $(\"l-clave\").value = \"\"; if(nombre) $(\"l-nom\").value = nombre;\n    showLogin(msg);\n  }\n  async function api(method, path, body){\n    var h = { \"X-Clave\": ses ? ses.clave : \"\", \"X-Usuario\": ses ? encodeURIComponent(ses.nombre) : \"\" };\n    if(body) h[\"Content-Type\"] = \"application/json\";\n    var res = await fetch(path, { method: method, headers: h, body: body ? JSON.stringify(body) : undefined, cache: \"no-store\" });\n    if(!res.ok){\n      var msg = \"Error \" + res.status;\n      try{ var j = await res.json(); if(j && j.error) msg = j.error; }catch(e){}\n      var err = new Error(msg); err.status = res.status;\n      if(res.status === 401 && path !== \"/api/sesion\") logout(\"Tu clave ya no es válida. Ingresa de nuevo.\");\n      throw err;\n    }\n    return res.json();\n  }\n  $(\"l-form\").addEventListener(\"submit\", async function(e){\n    e.preventDefault();\n    var n = $(\"l-nom\").value.trim(), c = $(\"l-clave\").value, er = $(\"l-err\"), b = $(\"l-btn\");\n    if(!n || !c){ er.textContent = \"Escribe tu nombre y la clave.\"; er.classList.remove(\"hidden\"); return; }\n    b.disabled = true; b.textContent = \"Verificando…\";\n    ses = { nombre: n.slice(0,40), clave: c };\n    try{\n      var r = await api(\"GET\", \"/api/sesion\");\n      ses.rol = r.rol; saveSes(); startApp();\n    }catch(ex){\n      ses = null;\n      er.textContent = ex.status === 401 ? \"Clave incorrecta.\" : (ex.status === 500 ? ex.message : \"No se pudo conectar con el servidor.\");\n      er.classList.remove(\"hidden\");\n    }\n    b.disabled = false; b.textContent = \"Entrar\";\n  });\n  $(\"btn-out\").onclick = function(){ logout(); };\n\n  function startApp(){\n    $(\"login\").classList.add(\"hidden\"); $(\"app\").classList.remove(\"hidden\");\n    document.body.classList.toggle(\"rol-admin\", isAdmin());\n    document.body.classList.toggle(\"rol-transportista\", !isAdmin());\n    $(\"u-av\").textContent = (ses.nombre[0] || \"?\").toUpperCase();\n    $(\"u-nom\").textContent = ses.nombre;\n    $(\"u-rol\").textContent = \"· \" + (ROL[ses.rol] || ses.rol);\n    resetFilters(true);\n    load(false);\n    if(pollTimer) clearInterval(pollTimer);\n    pollTimer = setInterval(function(){ if(!document.hidden && !$(\"modal-root\").innerHTML) load(true); }, 15000);\n  }\n  document.addEventListener(\"visibilitychange\", function(){ if(!document.hidden && ses && ses.rol) load(true); });\n\n  /* ---------- Datos ---------- */\n  async function load(silent){\n    if(busy || !ses) return;\n    try{\n      var data = await api(\"GET\", API);\n      if(busy) return;\n      regs = Array.isArray(data) ? data : [];\n      setSync(\"Actualizado \" + hora(), true);\n      render();\n    }catch(e){\n      if(e.status === 401) return;\n      setSync(\"Sin conexión\", false);\n      if(!silent) toast(\"No se pudieron cargar los registros.\");\n    }\n  }\n  function put(id, body){\n    busy++;\n    var i = regs.findIndex(function(r){ return r.id===id; });\n    var prev = i>=0 ? regs[i] : null;\n    var rec = Object.assign({ id:id }, body);\n    if(i>=0) regs[i]=rec; else regs.push(rec);\n    render();\n    return api(\"PUT\", API + \"/\" + encodeURIComponent(id), body).then(function(){\n      busy--; setSync(\"Actualizado \" + hora(), true);\n    }).catch(function(e){\n      busy--;\n      var j = regs.findIndex(function(r){ return r.id===id; });\n      if(prev) regs[j] = prev; else if(j>=0) regs.splice(j,1);\n      render();\n      if(e.status !== 401) toast(e.status===403 ? \"No tienes permiso para este cambio.\" : \"No se pudo guardar: \" + e.message);\n      throw e;\n    });\n  }\n  function del(id){\n    busy++;\n    var prev = regs.slice();\n    regs = regs.filter(function(r){ return r.id!==id; }); render();\n    return api(\"DELETE\", API + \"/\" + encodeURIComponent(id)).then(function(){ busy--; }).catch(function(e){\n      busy--; regs = prev; render(); if(e.status !== 401) toast(\"No se pudo eliminar.\");\n    });\n  }\n\n  async function setDescargado(ids, val){\n    var prev = [];\n    ids.forEach(function(id){ var r = regs.find(function(x){ return x.id===id; }); if(r) prev.push({id:id, d:!!r.descargado, f:r.fechaDescarga||\"\"}); });\n    var targets = prev.filter(function(p){ return p.d !== val; });\n    if(!targets.length) return;\n    targets.forEach(function(p){ flash.add(p.id); });\n    try{\n      for(var i=0;i<targets.length;i++){\n        var r = regs.find(function(x){ return x.id===targets[i].id; }); if(!r) continue;\n        var b = bodyOf(r); b.descargado = val; b.fechaDescarga = val ? (r.fechaDescarga || today()) : \"\"; b.actualizado = new Date().toISOString();\n        await put(r.id, b);\n      }\n    }catch(e){ return; }\n    setTimeout(function(){ flash.clear(); }, 950);\n    var n = targets.length;\n    toast((n===1 ? \"Referencia \" : n+\" referencias \") + (val ? (n>1?\"confirmadas\":\"confirmada\")+\" como descargada\"+(n>1?\"s\":\"\") : \"marcada\"+(n>1?\"s\":\"\")+\" como pendiente\"+(n>1?\"s\":\"\")),\n      function(){\n        (async function(){\n          for(var i=0;i<targets.length;i++){\n            var r = regs.find(function(x){ return x.id===targets[i].id; }); if(!r) continue;\n            var b = bodyOf(r); b.descargado = targets[i].d; b.fechaDescarga = targets[i].f; b.actualizado = new Date().toISOString();\n            try{ await put(r.id, b); }catch(e){ return; }\n          }\n        })();\n      });\n  }\n\n  /* ---------- Unidades ---------- */\n  function unitsFor(fecha, tipo){\n    var m = {};\n    regs.forEach(function(r){ if(r.fechaRetiro===fecha && r.tipo===tipo && r.unidad){ (m[r.unidad] = m[r.unidad] || []).push(r); } });\n    var nums = Object.keys(m).map(Number).sort(function(a,b){ return a-b; });\n    return { list: nums.map(function(n){ return { n:n, refs:m[n] }; }), next: nums.length ? nums[nums.length-1]+1 : 1 };\n  }\n  function unitOptions(fecha, tipo, current){\n    var u = unitsFor(fecha, tipo);\n    var last = u.list.length ? u.list[u.list.length-1].n : null;\n    var pick = current ? current : last;\n    var html = u.list.map(function(x){\n      return '<option value=\"'+x.n+'\"'+(String(pick)===String(x.n)?\" selected\":\"\")+'>Sumar a '+esc(unitLabel(tipo,x.n))+' (lleva '+x.refs.length+' ref.)</option>';\n    }).join(\"\");\n    html += '<option value=\"new\"'+(!pick?\" selected\":\"\")+'>Nueva unidad: '+esc(unitLabel(tipo,u.next))+'</option>';\n    return html;\n  }\n\n  /* ---------- Filtros ---------- */\n  function readFilters(){\n    F.emb = $(\"f-emb\").value.trim().toLowerCase();\n    F.ref = $(\"f-ref\").value.trim().toLowerCase();\n    F.alm = $(\"f-alm\").value.trim().toLowerCase();\n    F.bod = $(\"f-bod\").value.trim().toLowerCase();\n    F.desde = $(\"f-desde\").value; F.hasta = $(\"f-hasta\").value;\n    F.todas = $(\"f-todas\").checked; F.estado = $(\"f-est\").value;\n    $(\"f-desde\").disabled = F.todas; $(\"f-hasta\").disabled = F.todas;\n  }\n  function resetFilters(silent){\n    [\"f-emb\",\"f-ref\",\"f-alm\",\"f-bod\"].forEach(function(id){ $(id).value = \"\"; });\n    $(\"f-desde\").value = today(); $(\"f-hasta\").value = today();\n    $(\"f-todas\").checked = false; $(\"f-est\").value = \"all\";\n    readFilters(); sel.clear();\n    if(!silent) render();\n  }\n  function applyFilters(){ readFilters(); sel.clear(); render(); }\n  function has(v, q){ return !q || (v||\"\").toLowerCase().indexOf(q) >= 0; }\n  function baseFiltered(){\n    return regs.filter(function(r){\n      if(!F.todas){\n        if((F.desde || F.hasta) && !r.fechaRetiro) return false;\n        if(F.desde && r.fechaRetiro < F.desde) return false;\n        if(F.hasta && r.fechaRetiro > F.hasta) return false;\n      }\n      return has(r.embarque,F.emb) && has(r.referencia,F.ref) && has(r.almacenadora,F.alm) && has(r.bodega,F.bod);\n    });\n  }\n  function filtered(){\n    var rows = baseFiltered().filter(function(r){ return F.estado===\"all\" || (F.estado===\"d\" ? !!r.descargado : !r.descargado); });\n    var k = sortKey;\n    return rows.sort(function(a,b){\n      var va, vb;\n      if(k===\"transporte\"){ va=(a.tipo||\"~\")+String(a.unidad||0).padStart(3,\"0\"); vb=(b.tipo||\"~\")+String(b.unidad||0).padStart(3,\"0\"); }\n      else if(k===\"estado\"){ va=a.descargado?1:0; vb=b.descargado?1:0; }\n      else { va=(a[k]||\"\").toString().toLowerCase(); vb=(b[k]||\"\").toString().toLowerCase(); }\n      if(va===vb) return (a.referencia||\"\").localeCompare(b.referencia||\"\");\n      if(va===\"\") return 1; if(vb===\"\") return -1;\n      return (va<vb?-1:1)*sortDir;\n    });\n  }\n\n  /* ---------- Registros ---------- */\n  function thS(key, label){\n    var ar = sortKey===key ? '<span class=\"ar\">'+(sortDir>0?\"▲\":\"▼\")+'</span>' : \"\";\n    return '<th data-sort=\"'+key+'\" aria-sort=\"'+(sortKey===key?(sortDir>0?\"ascending\":\"descending\"):\"none\")+'\">'+label+ar+'</th>';\n  }\n  function emptyMsg(){\n    if(!regs.length) return isAdmin() ? '<strong>Aún no hay registros</strong>Pulsa “+ Nuevo registro” para empezar.' : '<strong>Aún no hay registros</strong>';\n    var dateOn = !F.todas && (F.desde || F.hasta);\n    var base = baseFiltered().length;\n    if(base && F.estado!==\"all\") return '<strong>No hay referencias '+(F.estado===\"p\"?\"pendientes\":\"descargadas\")+' con estos filtros</strong>Hay '+base+' referencia(s) sin filtrar por estado.';\n    if(dateOn) return '<strong>No hay referencias para '+(F.desde===F.hasta?\"el \"+esc(fmt(F.desde)):\"estas fechas\")+'</strong><button class=\"btn sm ghost\" type=\"button\" data-allfechas style=\"margin-top:10px\">Ver todas las fechas</button>';\n    return '<strong>Sin resultados</strong>Ajusta los filtros.';\n  }\n  function renderRecords(){\n    var rows = filtered(), admin = isAdmin();\n    $(\"count\").textContent = \"· \" + rows.length;\n    var head = '<thead><tr><th><input type=\"checkbox\" class=\"chk\" id=\"chk-all\" aria-label=\"Seleccionar todo\"></th>'+\n      thS(\"embarque\",\"Embarque\")+thS(\"referencia\",\"Referencia\")+thS(\"almacenadora\",\"Almacenadora\")+thS(\"fechaDocs\",\"Entrega docs.\")+\n      thS(\"fechaRetiro\",\"Fecha retiro\")+thS(\"bodega\",\"Bodega\")+thS(\"transporte\",\"Transporte\")+thS(\"estado\",\"Descarga en CD\")+(admin?'<th></th>':'')+'</tr></thead>';\n    if(!rows.length){\n      var msg = emptyMsg();\n      $(\"tbl\").innerHTML = head + '<tbody><tr><td colspan=\"10\"><div class=\"empty\">'+msg+'</div></td></tr></tbody>';\n      $(\"cards\").innerHTML = '<div class=\"empty\">'+msg+'</div>';\n    } else {\n      var acts = function(r){ return admin ? '<button class=\"icon-btn\" data-edit=\"'+esc(r.id)+'\" title=\"Editar\" aria-label=\"Editar\">✎</button><button class=\"icon-btn del\" data-del=\"'+esc(r.id)+'\" title=\"Eliminar\" aria-label=\"Eliminar\">✕</button>' : ''; };\n      $(\"tbl\").innerHTML = head + '<tbody>' + rows.map(function(r){\n        var cls = (r.descargado?\"d\":\"\")+(flash.has(r.id)?\" flash\":\"\");\n        return '<tr class=\"'+cls+'\"><td><input type=\"checkbox\" class=\"chk\" data-sel=\"'+esc(r.id)+'\"'+(sel.has(r.id)?\" checked\":\"\")+' aria-label=\"Seleccionar '+esc(r.referencia)+'\"></td>'+\n          '<td>'+esc(r.embarque||\"—\")+'</td><td class=\"ref\">'+esc(r.referencia)+'</td><td>'+esc(r.almacenadora||\"—\")+'</td>'+\n          '<td>'+esc(fmt(r.fechaDocs))+'</td><td>'+esc(fmt(r.fechaRetiro))+'</td><td>'+esc(r.bodega||\"—\")+'</td><td>'+tagHtml(r)+'</td><td>'+stHtml(r)+'</td>'+\n          (admin?'<td style=\"white-space:nowrap\">'+acts(r)+'</td>':'')+'</tr>';\n      }).join(\"\") + '</tbody>';\n      $(\"cards\").innerHTML = rows.map(function(r){\n        var cls = (r.descargado?\" d\":\"\")+(flash.has(r.id)?\" flash\":\"\");\n        return '<div class=\"rcard'+cls+'\"><input type=\"checkbox\" class=\"chk\" data-sel=\"'+esc(r.id)+'\"'+(sel.has(r.id)?\" checked\":\"\")+' aria-label=\"Seleccionar\">'+\n          '<div><div class=\"ref\">'+esc(r.referencia)+'</div><div style=\"margin-top:2px\">'+tagHtml(r)+'</div></div>'+\n          '<div class=\"acts\">'+acts(r)+'</div>'+\n          '<div class=\"meta\"><span>Embarque: <b>'+esc(r.embarque||\"—\")+'</b></span><span>Bodega: <b>'+esc(r.bodega||\"—\")+'</b></span>'+\n          '<span>Almacenadora: <b>'+esc(r.almacenadora||\"—\")+'</b></span><span>Retiro: <b>'+esc(fmt(r.fechaRetiro))+'</b></span>'+\n          '<span>Entrega docs.: <b>'+esc(fmt(r.fechaDocs))+'</b></span></div><div class=\"stw\">'+stHtml(r)+'</div></div>';\n      }).join(\"\");\n    }\n    var all = $(\"chk-all\");\n    if(all) all.checked = rows.length>0 && rows.every(function(r){ return sel.has(r.id); });\n    sel.forEach(function(id){ if(!regs.some(function(r){ return r.id===id; })) sel.delete(id); });\n    $(\"selbar\").classList.toggle(\"hidden\", sel.size===0);\n    $(\"selcount\").textContent = sel.size + (sel.size===1 ? \" seleccionada\" : \" seleccionadas\");\n  }\n  function renderLists(){\n    function uniq(k){ return Array.from(new Set(regs.map(function(r){ return (r[k]||\"\").trim(); }).filter(Boolean))).sort(); }\n    $(\"dl-alm\").innerHTML = uniq(\"almacenadora\").map(function(v){ return '<option value=\"'+esc(v)+'\">'; }).join(\"\");\n    $(\"dl-bod\").innerHTML = uniq(\"bodega\").map(function(v){ return '<option value=\"'+esc(v)+'\">'; }).join(\"\");\n  }\n\n  /* ---------- Estadísticas ---------- */\n  function statsRows(){\n    var from = $(\"s-from\").value, to = $(\"s-to\").value;\n    return regs.filter(function(r){ return r.fechaRetiro && (!from || r.fechaRetiro>=from) && (!to || r.fechaRetiro<=to); });\n  }\n  function statsData(){\n    var rs = statsRows();\n    function group(keyFn){\n      var m = {};\n      rs.forEach(function(r){\n        var k = keyFn(r) || \"(Sin dato)\";\n        var g = m[k] || (m[k] = { k:k, refs:0, d:0, cam:new Set(), cont:new Set(), sin:0 });\n        g.refs++; if(r.descargado) g.d++;\n        var uk = unitKey(r);\n        if(uk) (r.tipo===\"camion\" ? g.cam : g.cont).add(uk); else g.sin++;\n      });\n      return Object.keys(m).map(function(k){ var g=m[k]; return { k:k, refs:g.refs, d:g.d, cam:g.cam.size, cont:g.cont.size, tot:g.cam.size+g.cont.size, sin:g.sin }; });\n    }\n    var all = group(function(){ return \"Total\"; })[0] || { refs:0, d:0, cam:0, cont:0, tot:0, sin:0 };\n    return {\n      all: all,\n      fecha: group(function(r){ return r.fechaRetiro; }).sort(function(a,b){ return a.k<b.k?1:-1; }),\n      alm: group(function(r){ return (r.almacenadora||\"\").trim(); }).sort(function(a,b){ return b.refs-a.refs || a.k.localeCompare(b.k); }),\n      bod: group(function(r){ return (r.bodega||\"\").trim(); }).sort(function(a,b){ return b.refs-a.refs || a.k.localeCompare(b.k); })\n    };\n  }\n  function pctCell(g){\n    var p = g.refs ? Math.round(g.d/g.refs*100) : 0;\n    return '<span class=\"pct\"><span class=\"prog\"><i style=\"width:'+p+'%\"></i></span>'+g.d+'/'+g.refs+'</span>';\n  }\n  function statTable(rows, label, kind, total){\n    var head = '<thead><tr><th>'+label+'</th><th class=\"n\">Referencias</th><th class=\"n\">Camiones 8 ton</th><th class=\"n\">Contenedores</th><th>Total unidades</th><th class=\"n\">Descargadas en CD</th><th class=\"n\">Sin transporte</th></tr></thead>';\n    if(!rows.length) return head + '<tbody><tr><td colspan=\"7\"><div class=\"empty\">Sin retiros en el periodo.</div></td></tr></tbody>';\n    var max = Math.max.apply(null, rows.map(function(g){ return g.tot; }).concat([1]));\n    var body = rows.map(function(g){\n      var attr = g.k===\"(Sin dato)\" ? \"\" : ' data-goto-'+kind+'=\"'+esc(g.k)+'\"';\n      return '<tr class=\"'+(attr?\"click\":\"\")+'\"'+attr+'><td>'+esc(kind===\"fecha\"?fmt(g.k):g.k)+'</td><td class=\"n\">'+g.refs+'</td><td class=\"n\">'+g.cam+'</td><td class=\"n\">'+g.cont+'</td>'+\n        '<td><span class=\"minibar\" style=\"width:'+Math.max(4,Math.round(g.tot/max*80))+'px\"></span><b>'+g.tot+'</b></td><td class=\"n\">'+pctCell(g)+'</td><td class=\"n\">'+(g.sin||\"—\")+'</td></tr>';\n    }).join(\"\");\n    if(total) body += '<tr class=\"total\"><td>Total</td><td class=\"n\">'+total.refs+'</td><td class=\"n\">'+total.cam+'</td><td class=\"n\">'+total.cont+'</td><td><b>'+total.tot+'</b></td><td class=\"n\">'+pctCell(total)+'</td><td class=\"n\">'+(total.sin||\"—\")+'</td></tr>';\n    return head + '<tbody>'+body+'</tbody>';\n  }\n  function renderChart(rows){\n    var data = rows.slice().sort(function(a,b){ return a.k<b.k?-1:1; });\n    if(!data.length){ $(\"chart\").innerHTML = '<div class=\"empty\">Sin retiros en el periodo.</div>'; return; }\n    var max = Math.max.apply(null, data.map(function(g){ return g.tot; }).concat([1])), H = 130;\n    $(\"chart\").innerHTML = '<div class=\"bars\">'+data.map(function(g){\n      var h1 = Math.round(g.cam/max*H), h2 = Math.round(g.cont/max*H);\n      return '<button type=\"button\" class=\"bcol\" data-goto-fecha=\"'+esc(g.k)+'\" data-tip=\"'+esc(fmt(g.k)+\"|\"+g.cam+\"|\"+g.cont+\"|\"+g.refs+\"|\"+g.d)+'\" aria-label=\"'+esc(fmt(g.k))+': '+g.tot+' unidades\">'+\n        '<span class=\"v\">'+g.tot+'</span><span class=\"bstack\" style=\"height:'+(h1+h2)+'px\"><i class=\"c1\" style=\"height:'+h1+'px\"></i><i class=\"c2\" style=\"height:'+h2+'px\"></i></span></button>';\n    }).join(\"\")+'</div><div class=\"blab\">'+data.map(function(g){ return '<span>'+esc(fmtShort(g.k))+'</span>'; }).join(\"\")+'</div>';\n  }\n  function renderStats(){\n    var s = statsData(), p = s.all.refs ? Math.round(s.all.d/s.all.refs*100) : 0;\n    $(\"kpis\").innerHTML =\n      '<div class=\"card kpi\"><b>'+s.all.refs+'</b><span>Referencias retiradas</span></div>'+\n      '<div class=\"card kpi red\"><b>'+s.all.cam+'</b><span>Camiones 8 ton</span></div>'+\n      '<div class=\"card kpi\"><b>'+s.all.cont+'</b><span>Contenedores</span></div>'+\n      '<div class=\"card kpi red\"><b>'+s.all.tot+'</b><span>Total unidades</span></div>'+\n      '<div class=\"card kpi okk wide\"><b>'+p+'%</b><span>Descargado en CD ('+s.all.d+' de '+s.all.refs+')</span><div class=\"prog\"><i style=\"width:'+p+'%\"></i></div></div>';\n    renderChart(s.fecha);\n    $(\"t-fecha\").innerHTML = statTable(s.fecha, \"Fecha de retiro\", \"fecha\", s.all);\n    $(\"t-alm\").innerHTML = statTable(s.alm, \"Almacenadora\", \"alm\");\n    $(\"t-bod\").innerHTML = statTable(s.bod, \"Bodega\", \"bod\");\n    Array.prototype.forEach.call(document.querySelectorAll(\"#qr button\"), function(b){ b.classList.toggle(\"on\", b.dataset.range===qRange); });\n  }\n\n  function render(){\n    if(!ses || !ses.rol) return;\n    renderLists();\n    if(view===\"reg\") renderRecords(); else renderStats();\n  }\n\n  /* ---------- Modales ---------- */\n  function closeModal(){ $(\"modal-root\").innerHTML = \"\"; }\n  function openModal(title, bodyHtml, footHtml){\n    $(\"modal-root\").innerHTML = '<div class=\"ov\" id=\"ov\"><div class=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"'+esc(title)+'\">'+\n      '<header><h2>'+esc(title)+'</h2><button class=\"icon-btn\" id=\"m-x\" aria-label=\"Cerrar\" type=\"button\">✕</button></header>'+\n      '<div class=\"body\">'+bodyHtml+'</div><footer>'+footHtml+'</footer></div></div>';\n    $(\"m-x\").onclick = closeModal;\n    $(\"ov\").addEventListener(\"mousedown\", function(e){ if(e.target.id===\"ov\") closeModal(); });\n  }\n  document.addEventListener(\"keydown\", function(e){ if(e.key===\"Escape\") closeModal(); });\n\n  function openForm(rec){\n    if(!isAdmin()) return;\n    var r = rec || {};\n    var defFecha = r.fechaRetiro || (!F.todas && F.desde && F.desde===F.hasta ? F.desde : \"\");\n    openModal(rec ? \"Editar registro\" : \"Nuevo registro\",\n      '<label class=\"fl\">Embarque<input type=\"text\" id=\"m-emb\" value=\"'+esc(r.embarque)+'\"></label>'+\n      '<label class=\"fl\">Referencia *<input type=\"text\" id=\"m-ref\" value=\"'+esc(r.referencia)+'\" required></label>'+\n      '<label class=\"fl\">Almacenadora<input type=\"text\" id=\"m-alm\" list=\"dl-alm\" value=\"'+esc(r.almacenadora)+'\"></label>'+\n      '<label class=\"fl\">Bodega<input type=\"text\" id=\"m-bod\" list=\"dl-bod\" value=\"'+esc(r.bodega)+'\"></label>'+\n      '<label class=\"fl\">Fecha entrega de documentación<input type=\"date\" id=\"m-fdoc\" value=\"'+esc(r.fechaDocs)+'\"></label>'+\n      '<label class=\"fl\">Fecha de retiro<input type=\"date\" id=\"m-fret\" value=\"'+esc(defFecha)+'\"></label>'+\n      '<fieldset class=\"fieldset\"><legend>Transporte</legend>'+\n        '<label class=\"fl\">Tipo<select id=\"m-tipo\"><option value=\"\">Sin asignar</option><option value=\"camion\"'+(r.tipo===\"camion\"?\" selected\":\"\")+'>Camión 8 ton</option><option value=\"contenedor\"'+(r.tipo===\"contenedor\"?\" selected\":\"\")+'>Contenedor</option></select></label>'+\n        '<label class=\"fl\">Unidad<select id=\"m-uni\"></select></label>'+\n        '<p class=\"hint\" id=\"m-uhint\"></p>'+\n      '</fieldset>'+\n      '<fieldset class=\"fieldset'+(r.descargado?\" okf\":\"\")+'\" id=\"m-dfs\"><legend>Centro de distribución</legend>'+\n        '<label class=\"switch\"><input type=\"checkbox\" id=\"m-desc\"'+(r.descargado?\" checked\":\"\")+'> Descargado en CD</label>'+\n        '<label class=\"fl\">Fecha de descarga<input type=\"date\" id=\"m-fdes\" value=\"'+esc(r.fechaDescarga)+'\"'+(r.descargado?\"\":\" disabled\")+'></label>'+\n      '</fieldset>'+\n      '<p class=\"err hidden\" id=\"m-err\"></p>',\n      '<button class=\"btn plain\" id=\"m-cancel\" type=\"button\">Cancelar</button><button class=\"btn\" id=\"m-save\" type=\"button\">Guardar</button>');\n    function uhint(){\n      var h=$(\"m-uhint\"), t=$(\"m-tipo\").value, v=$(\"m-uni\").value, nom = t===\"contenedor\" ? \"contenedor\" : \"camión\";\n      if(!t || !$(\"m-fret\").value){ h.textContent=\"Las referencias asignadas a la misma unidad el mismo día cuentan como 1 solo camión o contenedor.\"; return; }\n      h.textContent = v===\"new\" ? \"Esta referencia abrirá un \"+nom+\" adicional para ese día.\" : \"Se suma a un \"+nom+\" que ya existe ese día: no aumenta el conteo de unidades.\";\n    }\n    function syncUnit(){\n      var t=$(\"m-tipo\").value, f=$(\"m-fret\").value, u=$(\"m-uni\");\n      if(!t || !f){ u.innerHTML='<option value=\"\">'+(t?\"Primero indica la fecha de retiro\":\"—\")+'</option>'; u.disabled=true; uhint(); return; }\n      u.disabled=false;\n      var keep = (rec && rec.tipo===t && rec.fechaRetiro===f) ? rec.unidad : null;\n      u.innerHTML = unitOptions(f, t, keep); uhint();\n    }\n    $(\"m-uni\").onchange = uhint; $(\"m-tipo\").onchange = syncUnit; $(\"m-fret\").onchange = syncUnit; syncUnit();\n    $(\"m-desc\").onchange = function(){\n      var on = this.checked; $(\"m-fdes\").disabled = !on; $(\"m-dfs\").classList.toggle(\"okf\", on);\n      if(on && !$(\"m-fdes\").value) $(\"m-fdes\").value = today();\n    };\n    $(\"m-cancel\").onclick = closeModal;\n    $(\"m-ref\").focus();\n    $(\"m-save\").onclick = function(){\n      var err=$(\"m-err\"), ref=$(\"m-ref\").value.trim(), tipo=$(\"m-tipo\").value, fret=$(\"m-fret\").value;\n      if(!ref){ err.textContent=\"La referencia es obligatoria.\"; err.classList.remove(\"hidden\"); return; }\n      if(tipo && !fret){ err.textContent=\"Indica la fecha de retiro para asignar transporte.\"; err.classList.remove(\"hidden\"); return; }\n      var uv=$(\"m-uni\").value, unidad=null;\n      if(tipo) unidad = uv===\"new\" ? unitsFor(fret,tipo).next : parseInt(uv,10);\n      var dsc = $(\"m-desc\").checked;\n      var body = {\n        embarque:$(\"m-emb\").value.trim(), referencia:ref, almacenadora:$(\"m-alm\").value.trim(), bodega:$(\"m-bod\").value.trim(),\n        fechaDocs:$(\"m-fdoc\").value||\"\", fechaRetiro:fret||\"\", tipo:tipo||null, unidad:unidad,\n        descargado:dsc, fechaDescarga: dsc ? ($(\"m-fdes\").value || today()) : \"\",\n        creado:(rec && rec.creado) || new Date().toISOString(), actualizado:new Date().toISOString()\n      };\n      var btn = this; btn.disabled = true;\n      var id = rec ? rec.id : newId();\n      flash.add(id);\n      put(id, body).then(function(){ closeModal(); toast(rec?\"Registro actualizado\":\"Registro guardado\"); setTimeout(function(){ flash.clear(); }, 950); }).catch(function(){ btn.disabled=false; });\n    };\n  }\n\n  function openAssign(){\n    if(!isAdmin()) return;\n    var chosen = regs.filter(function(r){ return sel.has(r.id); });\n    var fechas = Array.from(new Set(chosen.map(function(r){ return r.fechaRetiro||\"\"; })));\n    var problem = fechas.indexOf(\"\")>=0 ? \"Todas las referencias seleccionadas necesitan fecha de retiro.\" :\n                  fechas.length>1 ? \"Las referencias seleccionadas tienen fechas de retiro distintas. Una unidad solo puede ser de un día.\" : \"\";\n    var f = fechas[0];\n    openModal(\"Asignar transporte\",\n      '<p class=\"hint full\"><b>'+chosen.length+'</b> referencia(s): '+chosen.map(function(r){ return esc(r.referencia); }).join(\", \")+'</p>'+\n      (problem ? '<p class=\"err\">'+esc(problem)+'</p>' :\n        '<p class=\"hint full\">Fecha de retiro: <b>'+esc(fmt(f))+'</b></p>'+\n        '<label class=\"fl\">Tipo<select id=\"a-tipo\"><option value=\"camion\">Camión 8 ton</option><option value=\"contenedor\">Contenedor</option></select></label>'+\n        '<label class=\"fl\">Unidad<select id=\"a-uni\"></select></label>'+\n        '<p class=\"hint\">Todas estas referencias contarán como <b>una sola unidad</b> ese día.</p>'),\n      problem ? '<button class=\"btn\" id=\"a-close\" type=\"button\">Entendido</button>' :\n        '<button class=\"btn plain\" id=\"a-clear\" type=\"button\">Quitar transporte</button><button class=\"btn\" id=\"a-ok\" type=\"button\">Asignar</button>');\n    if(problem){ $(\"a-close\").onclick = closeModal; return; }\n    function sync(){ $(\"a-uni\").innerHTML = unitOptions(f, $(\"a-tipo\").value, null); }\n    $(\"a-tipo\").onchange = sync; sync();\n    async function apply(tipo, unidad){\n      try{\n        for(var i=0;i<chosen.length;i++){\n          var r = chosen[i], body = bodyOf(r);\n          body.tipo = tipo; body.unidad = unidad; body.actualizado = new Date().toISOString();\n          flash.add(r.id);\n          await put(r.id, body);\n        }\n        sel.clear(); closeModal(); render();\n        setTimeout(function(){ flash.clear(); }, 950);\n        toast(tipo ? \"Asignadas a \"+unitLabel(tipo,unidad) : \"Transporte retirado\");\n      }catch(e){}\n    }\n    $(\"a-ok\").onclick = function(){ var t=$(\"a-tipo\").value, v=$(\"a-uni\").value; this.disabled = true; apply(t, v===\"new\" ? unitsFor(f,t).next : parseInt(v,10)); };\n    $(\"a-clear\").onclick = function(){ this.disabled = true; apply(null, null); };\n  }\n\n  function confirmDelete(id){\n    if(!isAdmin()) return;\n    var r = regs.find(function(x){ return x.id===id; }); if(!r) return;\n    openModal(\"Eliminar registro\", '<p class=\"hint full\" style=\"font-size:13px;color:var(--ink)\">¿Eliminar la referencia <b>'+esc(r.referencia)+'</b>? Esta acción no se puede deshacer.</p>',\n      '<button class=\"btn plain\" id=\"d-no\" type=\"button\">Cancelar</button><button class=\"btn\" id=\"d-yes\" type=\"button\">Eliminar</button>');\n    $(\"d-no\").onclick = closeModal;\n    $(\"d-yes\").onclick = function(){ sel.delete(id); del(id).then(function(){ closeModal(); toast(\"Registro eliminado\"); }); };\n  }\n\n  /* ---------- CSV ---------- */\n  function csvCell(v){ v = String(v==null?\"\":v); return /[\",;\\n]/.test(v) ? '\"'+v.replace(/\"/g,'\"\"')+'\"' : v; }\n  function exportCsv(){\n    var s = statsData(), lines = [];\n    function block(title, rows, isDate){\n      lines.push(csvCell(title));\n      lines.push([\"Grupo\",\"Referencias\",\"Camiones 8 ton\",\"Contenedores\",\"Total unidades\",\"Descargadas en CD\",\"Sin transporte\"].join(\",\"));\n      rows.forEach(function(g){ lines.push([csvCell(isDate?fmt(g.k):g.k), g.refs, g.cam, g.cont, g.tot, g.d, g.sin].join(\",\")); });\n      lines.push(\"\");\n    }\n    block(\"Por fecha de retiro\", s.fecha, true); block(\"Por almacenadora\", s.alm, false); block(\"Por bodega\", s.bod, false);\n    lines.push(\"Detalle de referencias\");\n    lines.push([\"Embarque\",\"Referencia\",\"Almacenadora\",\"Fecha entrega documentación\",\"Fecha retiro\",\"Bodega\",\"Transporte\",\"Descargado en CD\",\"Fecha descarga\"].join(\",\"));\n    statsRows().forEach(function(r){\n      lines.push([r.embarque,r.referencia,r.almacenadora,fmt(r.fechaDocs),fmt(r.fechaRetiro),r.bodega,(r.tipo&&r.unidad)?unitLabel(r.tipo,r.unidad):\"Sin asignar\",r.descargado?\"Sí\":\"No\",r.fechaDescarga?fmt(r.fechaDescarga):\"\"].map(csvCell).join(\",\"));\n    });\n    var blob = new Blob([\"\\ufeff\"+lines.join(\"\\n\")], {type:\"text/csv\"});\n    var a = document.createElement(\"a\"); a.href = URL.createObjectURL(blob); a.download = \"estadisticas-retiros.csv\";\n    document.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 500);\n  }\n\n  /* ---------- Eventos ---------- */\n  function setView(v){\n    view = v;\n    $(\"v-reg\").classList.toggle(\"hidden\", v!==\"reg\");\n    $(\"v-est\").classList.toggle(\"hidden\", v!==\"est\");\n    $(\"nav-reg\").classList.toggle(\"on\", v===\"reg\");\n    $(\"nav-est\").classList.toggle(\"on\", v===\"est\");\n    hideTip(); render(); window.scrollTo(0,0);\n  }\n  $(\"nav-reg\").onclick = function(){ setView(\"reg\"); };\n  $(\"nav-est\").onclick = function(){ setView(\"est\"); };\n  $(\"btn-new\").onclick = function(){ openForm(null); };\n  $(\"f-go\").onclick = applyFilters;\n  $(\"f-reset\").onclick = function(){ resetFilters(false); };\n  [\"f-emb\",\"f-ref\",\"f-alm\",\"f-bod\"].forEach(function(id){ $(id).addEventListener(\"keydown\", function(e){ if(e.key===\"Enter\") applyFilters(); }); });\n  [\"f-desde\",\"f-hasta\",\"f-est\",\"f-todas\"].forEach(function(id){ $(id).addEventListener(\"change\", function(){\n    if(id===\"f-desde\" && $(\"f-desde\").value && (!$(\"f-hasta\").value || $(\"f-hasta\").value < $(\"f-desde\").value)) $(\"f-hasta\").value = $(\"f-desde\").value;\n    if(id===\"f-hasta\" && $(\"f-hasta\").value && $(\"f-desde\").value > $(\"f-hasta\").value) $(\"f-desde\").value = $(\"f-hasta\").value;\n    applyFilters();\n  }); });\n  $(\"btn-assign\").onclick = openAssign;\n  $(\"btn-markd\").onclick = function(){ var ids=Array.from(sel); sel.clear(); setDescargado(ids, true); render(); };\n  $(\"btn-markp\").onclick = function(){ var ids=Array.from(sel); sel.clear(); setDescargado(ids, false); render(); };\n  $(\"btn-unsel\").onclick = function(){ sel.clear(); render(); };\n  $(\"s-from\").onchange = function(){ qRange=\"\"; render(); };\n  $(\"s-to\").onchange = function(){ qRange=\"\"; render(); };\n  $(\"s-csv\").onclick = exportCsv;\n\n  $(\"v-reg\").addEventListener(\"click\", function(e){\n    var t = e.target;\n    if(t.id===\"chk-all\"){ filtered().forEach(function(r){ if(t.checked) sel.add(r.id); else sel.delete(r.id); }); renderRecords(); return; }\n    var s = t.getAttribute && t.getAttribute(\"data-sel\");\n    if(s){ if(t.checked) sel.add(s); else sel.delete(s); renderRecords(); return; }\n    var b = t.closest && t.closest(\"[data-edit],[data-del],[data-desc],[data-allfechas],th[data-sort]\");\n    if(!b) return;\n    if(b.dataset.desc){ var r0 = regs.find(function(x){ return x.id===b.dataset.desc; }); if(r0) setDescargado([r0.id], !r0.descargado); return; }\n    if(b.hasAttribute(\"data-allfechas\")){ $(\"f-todas\").checked = true; applyFilters(); return; }\n    if(b.dataset.sort){ var k=b.dataset.sort; if(sortKey===k) sortDir=-sortDir; else { sortKey=k; sortDir=(k===\"fechaRetiro\"||k===\"fechaDocs\")?-1:1; } renderRecords(); return; }\n    if(b.dataset.edit){ var r = regs.find(function(x){ return x.id===b.dataset.edit; }); if(r) openForm(r); return; }\n    if(b.dataset.del) confirmDelete(b.dataset.del);\n  });\n\n  $(\"v-est\").addEventListener(\"click\", function(e){\n    var b = e.target.closest && e.target.closest(\"[data-goto-fecha],[data-goto-alm],[data-goto-bod],[data-range]\");\n    if(!b) return;\n    if(b.dataset.range){\n      qRange = b.dataset.range;\n      if(qRange===\"all\"){ $(\"s-from\").value=\"\"; $(\"s-to\").value=\"\"; }\n      else if(qRange===\"mes\"){ var t=today(); $(\"s-from\").value=t.slice(0,8)+\"01\"; $(\"s-to\").value=t; }\n      else { $(\"s-from\").value=today(-(parseInt(qRange,10)-1)); $(\"s-to\").value=today(); }\n      render(); return;\n    }\n    [\"f-emb\",\"f-ref\",\"f-alm\",\"f-bod\"].forEach(function(id){ $(id).value = \"\"; });\n    $(\"f-est\").value = \"all\";\n    if(b.dataset.gotoFecha){ $(\"f-desde\").value = b.dataset.gotoFecha; $(\"f-hasta\").value = b.dataset.gotoFecha; $(\"f-todas\").checked = false; }\n    else {\n      if(b.dataset.gotoAlm) $(\"f-alm\").value = b.dataset.gotoAlm;\n      if(b.dataset.gotoBod) $(\"f-bod\").value = b.dataset.gotoBod;\n      $(\"f-desde\").value = $(\"s-from\").value; $(\"f-hasta\").value = $(\"s-to\").value;\n      $(\"f-todas\").checked = !$(\"s-from\").value && !$(\"s-to\").value;\n    }\n    readFilters(); sel.clear(); setView(\"reg\");\n  });\n\n  var tip = null;\n  function hideTip(){ if(tip){ tip.remove(); tip=null; } }\n  $(\"chart\").addEventListener(\"pointerover\", function(e){\n    var b = e.target.closest(\".bcol\"); if(!b) return;\n    var p = b.dataset.tip.split(\"|\");\n    hideTip(); tip = document.createElement(\"div\"); tip.className=\"tip\";\n    tip.textContent = p[0]+\" — \"+p[1]+\" camión(es), \"+p[2]+\" contenedor(es) · \"+p[3]+\" ref., \"+p[4]+\" descargadas\";\n    document.body.appendChild(tip);\n    var r = b.getBoundingClientRect(), w = tip.offsetWidth;\n    tip.style.left = Math.max(8, Math.min(window.innerWidth-w-8, r.left + r.width/2 - w/2))+\"px\";\n    tip.style.top = Math.max(8, r.top - tip.offsetHeight - 6)+\"px\";\n  });\n  $(\"chart\").addEventListener(\"pointerout\", function(e){ if(e.target.closest(\".bcol\")) hideTip(); });\n  window.addEventListener(\"scroll\", hideTip, {passive:true});\n\n  /* ---------- Inicio ---------- */\n  loadSes();\n  if(ses){\n    $(\"l-nom\").value = ses.nombre;\n    api(\"GET\", \"/api/sesion\").then(function(r){ ses.rol = r.rol; saveSes(); startApp(); })\n      .catch(function(e){ if(e.status === 401){ var n = ses.nombre; ses = null; try{ localStorage.removeItem(SES_KEY); }catch(x){} $(\"l-nom\").value = n; showLogin(\"Tu clave cambió. Ingresa de nuevo.\"); } else { ses.rol ? startApp() : showLogin(\"No se pudo conectar con el servidor.\"); } });\n  } else {\n    showLogin();\n  }\n})();\n</script>\n</body>\n</html>\n";
